class Solution:
    def targetIndices(self, nums: list[int], target: int) -> list[int]:
        less = equal = 0
        for v in nums:                     # one pass, no sorting: O(n)
            if v < target:
                less += 1                  # these occupy the indices before the target block
            elif v == target:
                equal += 1                 # these occupy the block itself
        return list(range(less, less + equal))   # sorted position of the target copies
